"use client";

import * as React from "react";
import { Folder, FolderPlus, Plus, RotateCcw } from "lucide-react";

type DivProps = React.ComponentProps<"div">;
type PendingGhostState = "in" | "out";

export type FirstItemTone = "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5" | "muted";

export type FirstItemStatus = { label: string; tone?: FirstItemTone };

export type FirstItem = {
  id: string;
  title: string;
  meta?: string;
  status?: FirstItemStatus;
  icon?: React.ReactNode;
};

export type FirstItemRowPhase = "materializing" | "settled";
export type FirstItemRowState = { phase: FirstItemRowPhase; typed: number };

export type FirstItemCopy = {
  title?: React.ReactNode;
  description?: React.ReactNode;
  createLabel?: string;
  creatingLabel?: string;
  retryLabel?: string;
  importLabel?: string;
  errorText?: string;
  /** Label of the small create button in the toolbar once the list has items. */
  toolbarCreateLabel?: string;
  icon?: React.ReactNode;
};

export type FirstItemEmptyStateProps = DivProps & {
  /** Controlled list. Leave undefined to let the component keep the list itself. */
  items?: FirstItem[];
  defaultItems?: FirstItem[];
  onItemsChange?: (items: FirstItem[]) => void;
  /** Return the created item, or a promise of it. Throw or reject to show the retry state. */
  onCreate: () => unknown;
  onImport?: () => void;
  onItemSelect?: (item: FirstItem) => void;
  /** Heading of the list, e.g. "Projects". */
  title?: string;
  /** Singular noun used in the generated copy and the count, e.g. "project". */
  noun?: string;
  nounPlural?: string;
  copy?: FirstItemCopy;
  /** Placeholder rows shown while the list is empty. */
  ghostRows?: number;
  /** Keep the list area at least this many rows tall once items exist. */
  minRows?: number;
  /** Milliseconds per typed character while a new row materializes. */
  typingSpeed?: number;
  renderItem?: (item: FirstItem, state: FirstItemRowState) => React.ReactNode;
  /** Header slot on the right of the title. */
  actions?: React.ReactNode;
};

const ROW = 52;
const GAP = 6;
const PITCH = ROW + GAP;
const BREATH = 2800;
const BREATH_STAGGER = 300;
const SHIMMER = 500;
const OVERLAY_OUT = 160;
const TOOLBAR = 260;
const GHOST_OUT = 380;
const GHOST_STAGGER = 40;
const LIFT = 560;
const LAND = 320;
const LEAVE = 280;
const LEAVE_STAGGER = 30;
const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const EASE_IN = "cubic-bezier(0.4, 0, 1, 1)";
const SWEEP = "cubic-bezier(0.4, 0, 0.2, 1)";
const GHOST_WIDTHS: [number, number][] = [[38, 26], [46, 22], [32, 30]];
const GHOST_CARD = "relative flex h-[52px] items-center gap-3 rounded-xl bg-muted/60 px-3 ring-1 ring-border";

const PILL: { [tone in FirstItemTone]: { pill: string; dot: string } } = {
  "chart-1": { pill: "bg-chart-1/15 text-foreground", dot: "bg-chart-1" },
  "chart-2": { pill: "bg-chart-2/15 text-foreground", dot: "bg-chart-2" },
  "chart-3": { pill: "bg-chart-3/15 text-foreground", dot: "bg-chart-3" },
  "chart-4": { pill: "bg-chart-4/20 text-foreground", dot: "bg-chart-4" },
  "chart-5": { pill: "bg-chart-5/15 text-foreground", dot: "bg-chart-5" },
  muted: { pill: "bg-muted text-muted-foreground", dot: "bg-muted-foreground/50" },
};

const BUTTON =
  "inline-flex h-8 shrink-0 items-center justify-center gap-1.5 rounded-lg px-3 text-xs font-medium outline-none transition-[background-color,color,opacity] duration-200 motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card disabled:cursor-default";
const PRIMARY = `${BUTTON} bg-primary text-primary-foreground hover:bg-primary/90 disabled:opacity-70`;
const GHOST = `${BUTTON} text-muted-foreground hover:bg-muted hover:text-foreground`;
const SMALL_PRIMARY = `${BUTTON} h-7 px-2.5 bg-primary text-primary-foreground hover:bg-primary/90 disabled:opacity-70`;
const SMALL_GHOST = `${BUTTON} h-7 px-2.5 text-muted-foreground hover:bg-muted hover:text-foreground`;

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

function isFirstItem(value: unknown): value is FirstItem {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as { id?: unknown; title?: unknown };
  return typeof candidate.id === "string" && typeof candidate.title === "string";
}

const wait = (ms: number) => new Promise((resolve) => window.setTimeout(resolve, ms));

function Shimmer() {
  const ref = React.useRef(null as HTMLSpanElement | null);
  React.useEffect(() => {
    const node = ref.current;
    if (!node || typeof node.animate !== "function") return;
    const animation = node.animate([{ transform: "translateX(-100%)" }, { transform: "translateX(300%)" }], { duration: SHIMMER, iterations: Number.POSITIVE_INFINITY, easing: SWEEP });
    return () => animation.cancel();
  }, []);
  return (
    <span data-shimmer aria-hidden="true" className="pointer-events-none absolute inset-0 overflow-hidden rounded-xl">
      <span ref={ref} className="absolute inset-y-0 left-0 w-1/3 bg-linear-to-r from-transparent via-foreground/10 to-transparent" />
    </span>
  );
}

function GhostBody({ index }: { index: number }) {
  const widths = GHOST_WIDTHS[index % GHOST_WIDTHS.length] ?? [38, 26];
  return (
    <>
      <span className="size-8 shrink-0 rounded-full bg-muted-foreground/18" />
      <span className="flex min-w-0 flex-1 flex-col gap-2">
        <span data-ghost-bar className="block h-2.5 rounded-full bg-muted-foreground/25" style={{ width: `${widths[0]}%` }} />
        <span className="block h-2 rounded-full bg-muted-foreground/15" style={{ width: `${widths[1]}%` }} />
      </span>
      <span className="h-5 w-14 shrink-0 rounded-full bg-muted-foreground/15" />
    </>
  );
}

type GhostRowProps = { index: number; appear: boolean; reduced: boolean; shimmer: boolean; register: (node: HTMLDivElement | null) => void };

function GhostRow({ index, appear, reduced, shimmer, register }: GhostRowProps) {
  const ref = React.useRef(null as HTMLLIElement | null);
  React.useLayoutEffect(() => {
    const node = ref.current;
    if (!appear || reduced || !node || typeof node.animate !== "function") return;
    const animation = node.animate([{ opacity: 0, transform: "translateY(6px)" }, { opacity: 1, transform: "translateY(0)" }], { duration: 320, delay: 80 + index * 50, easing: EASE, fill: "backwards" });
    return () => animation.cancel();
  }, []);
  return (
    <li ref={ref} data-ghost data-index={index} aria-hidden="true" className="py-[3px]">
      <div ref={register} data-ghost-card className={`${GHOST_CARD} opacity-60`}>
        <GhostBody index={index} />
        {shimmer && <Shimmer />}
      </div>
    </li>
  );
}

function CollapsingGhost({ index, order }: { index: number; order: number }) {
  const ref = React.useRef(null as HTMLLIElement | null);
  React.useLayoutEffect(() => {
    const node = ref.current;
    if (!node || typeof node.animate !== "function") return;
    const animation = node.animate(
      [{ height: `${PITCH}px`, opacity: 0.6, transform: "scale(1)" }, { height: "0px", opacity: 0, transform: "scale(0.985)" }],
      { duration: GHOST_OUT, delay: order * GHOST_STAGGER, easing: EASE_IN, fill: "forwards" },
    );
    return () => animation.cancel();
  }, []);
  return (
    <li ref={ref} data-ghost data-collapsing aria-hidden="true" className="overflow-hidden py-[3px]">
      <div className={GHOST_CARD}>
        <GhostBody index={index} />
      </div>
    </li>
  );
}

function PendingGhost({ state, reduced, onGone }: { state: PendingGhostState; reduced: boolean; onGone: () => void }) {
  const ref = React.useRef(null as HTMLLIElement | null);
  const gone = React.useRef(onGone);
  gone.current = onGone;
  React.useLayoutEffect(() => {
    const node = ref.current;
    if (!node || reduced || typeof node.animate !== "function") {
      if (state === "out") gone.current();
      return;
    }
    if (state === "in") {
      const animation = node.animate([{ height: "0px", opacity: 0 }, { height: `${PITCH}px`, opacity: 1 }], { duration: TOOLBAR, easing: EASE });
      return () => animation.cancel();
    }
    const animation = node.animate([{ height: `${PITCH}px`, opacity: 1 }, { height: "0px", opacity: 0 }], { duration: TOOLBAR, easing: EASE_IN, fill: "forwards" });
    animation.onfinish = () => gone.current();
    return () => animation.cancel();
  }, [state, reduced]);
  return (
    <li ref={ref} data-ghost data-pending-ghost data-state={state} aria-hidden="true" className="overflow-hidden py-[3px]">
      <div data-ghost-card className={`${GHOST_CARD} opacity-90`}>
        <GhostBody index={0} />
        {state === "in" && !reduced && <Shimmer />}
      </div>
    </li>
  );
}

type RowProps = {
  item: FirstItem;
  materialize: boolean;
  reduced: boolean;
  typingSpeed: number;
  focusOnMount: boolean;
  keyboardFocus: () => boolean;
  leaveOrder?: number;
  renderItem?: (item: FirstItem, state: FirstItemRowState) => React.ReactNode;
  onSettled?: (id: string) => void;
  onSelect?: (item: FirstItem) => void;
};

type PlaceholderRefs = { title?: HTMLSpanElement | null; meta?: HTMLSpanElement | null; pill?: HTMLSpanElement | null };

function Row({ item, materialize, reduced, typingSpeed, focusOnMount, keyboardFocus, leaveOrder, renderItem, onSettled, onSelect }: RowProps) {
  const length = item.title.length;
  const [typed, setTyped] = React.useState(length);
  const [phase, setPhase] = React.useState("settled" as FirstItemRowPhase);
  const [ring, setRing] = React.useState(false);
  const started = React.useRef(false);
  const liRef = React.useRef(null as HTMLLIElement | null);
  const cardRef = React.useRef(null as HTMLDivElement | null);
  const shadowRef = React.useRef(null as HTMLSpanElement | null);
  const skinRef = React.useRef(null as HTMLSpanElement | null);
  const iconRef = React.useRef(null as HTMLSpanElement | null);
  const glyphRef = React.useRef(null as HTMLSpanElement | null);
  const metaRef = React.useRef(null as HTMLParagraphElement | null);
  const pillRef = React.useRef(null as HTMLSpanElement | null);
  const placeholders = React.useRef({} as PlaceholderRefs);
  const settled = React.useRef(onSettled);
  settled.current = onSettled;
  const leaving = leaveOrder !== undefined;

  React.useLayoutEffect(() => {
    if (focusOnMount) liRef.current?.focus({ preventScroll: true });
  }, []);

  React.useLayoutEffect(() => {
    if (!materialize || started.current) return;
    started.current = true;
    const card = cardRef.current;
    if (reduced || !card || typeof card.animate !== "function") {
      settled.current?.(item.id);
      return;
    }
    setTyped(0);
    setPhase("materializing");
  }, [materialize, reduced]);

  React.useLayoutEffect(() => {
    const card = cardRef.current;
    if (phase !== "materializing" || !card) return;
    const typeMs = length * typingSpeed;
    const animations: Animation[] = [];
    animations.push(card.animate([{ transform: "scale(0.98)" }, { transform: "scale(1.006)", offset: 0.55 }, { transform: "scale(1)" }], { duration: LIFT, easing: EASE }));
    const shadow = shadowRef.current;
    if (shadow) animations.push(shadow.animate([{ opacity: 0 }, { opacity: 1, offset: 0.55 }, { opacity: 0 }], { duration: LIFT, easing: EASE }));
    const skin = skinRef.current;
    if (skin) animations.push(skin.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 300, easing: EASE }));
    const icon = iconRef.current;
    if (icon) {
      const computed = getComputedStyle(icon);
      animations.push(icon.animate(
        [{ borderRadius: "9999px", backgroundColor: "color-mix(in oklch, var(--color-muted-foreground) 15%, transparent)" }, { borderRadius: computed.borderRadius, backgroundColor: computed.backgroundColor }],
        { duration: 320, easing: EASE },
      ));
    }
    const glyph = glyphRef.current;
    if (glyph) animations.push(glyph.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 240, delay: 100, easing: EASE, fill: "backwards" }));
    const fade = (node: HTMLSpanElement | null | undefined, delay: number, duration: number) => {
      if (node) animations.push(node.animate([{ opacity: 1 }, { opacity: 0 }], { duration, delay, easing: EASE, fill: "forwards" }));
    };
    fade(placeholders.current.title, 0, 220);
    fade(placeholders.current.meta, Math.max(0, typeMs - 120), 240);
    fade(placeholders.current.pill, typeMs, 200);
    const meta = metaRef.current;
    if (meta) animations.push(meta.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 260, delay: Math.max(0, typeMs - 80), easing: EASE, fill: "backwards" }));
    const pill = pillRef.current;
    if (pill) animations.push(pill.animate([{ opacity: 0, transform: "translateY(-6px)" }, { opacity: 1, transform: "translateY(0)" }], { duration: LAND, delay: typeMs, easing: EASE, fill: "backwards" }));
    let frame = 0;
    const started = performance.now();
    const tick = (now: number) => {
      const next = Math.max(0, Math.min(length, Math.floor((now - started) / typingSpeed)));
      setTyped(next);
      if (next < length) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    const timer = window.setTimeout(() => {
      setPhase("settled");
      settled.current?.(item.id);
    }, typeMs + LAND);
    return () => {
      cancelAnimationFrame(frame);
      window.clearTimeout(timer);
      for (const animation of animations) animation.cancel();
    };
  }, [phase]);

  React.useLayoutEffect(() => {
    const node = liRef.current;
    if (!leaving || !node || typeof node.animate !== "function") return;
    const animation = node.animate([{ opacity: 1, transform: "translateY(0)" }, { opacity: 0, transform: "translateY(24px)" }], { duration: LEAVE, delay: leaveOrder * LEAVE_STAGGER, easing: EASE_IN, fill: "forwards" });
    return () => animation.cancel();
  }, []);

  const tone = item.status?.tone ?? "chart-2";
  const typing = phase === "materializing";
  const rest = item.title.slice(typed);

  return (
    <li
      ref={liRef}
      data-row
      data-id={item.id}
      data-phase={phase}
      data-typed={typed}
      data-focus-ring={ring ? "true" : "false"}
      aria-hidden={leaving ? "true" : undefined}
      tabIndex={leaving ? -1 : 0}
      onClick={leaving ? undefined : () => onSelect?.(item)}
      onFocus={(event) => { if (event.target === event.currentTarget) setRing(keyboardFocus()); }}
      onBlur={(event) => { if (event.target === event.currentTarget) setRing(false); }}
      className="group py-[3px] outline-none"
    >
      <div
        ref={cardRef}
        data-row-card
        className={`relative flex h-[52px] items-center gap-3 rounded-xl bg-card px-3 shadow-sm transition-colors duration-200 motion-reduce:transition-none group-hover:bg-muted/40 ${ring ? "ring-2 ring-ring" : "ring-1 ring-border"}`}
      >
        {typing && <span ref={shadowRef} data-lift-shadow aria-hidden="true" className="pointer-events-none absolute inset-0 rounded-xl opacity-0" style={{ boxShadow: "0 14px 28px -14px rgb(0 0 0 / 0.28)" }} />}
        {typing && <span ref={skinRef} data-ghost-skin aria-hidden="true" className="pointer-events-none absolute inset-0 rounded-xl bg-muted/60 opacity-0" />}
        {renderItem ? (
          <div className="relative flex min-w-0 flex-1 items-center gap-3">{renderItem(item, { phase, typed })}</div>
        ) : (
          <>
            <span ref={iconRef} data-icon className="relative flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground">
              <span ref={glyphRef} className="flex">{item.icon ?? <Folder className="size-4" aria-hidden="true" />}</span>
            </span>
            <div className="relative min-w-0 flex-1">
              {typing && <span ref={(node) => { placeholders.current.title = node; }} data-placeholder="title" aria-hidden="true" className="absolute left-0 top-[5px] h-2.5 w-[38%] rounded-full bg-muted-foreground/25" />}
              {typing && <span ref={(node) => { placeholders.current.meta = node; }} data-placeholder="meta" aria-hidden="true" className="absolute left-0 top-6 h-2 w-[26%] rounded-full bg-muted-foreground/15" />}
              <p className="relative truncate text-sm font-medium leading-5">
                <span data-title>{item.title.slice(0, typed)}</span>
                {typing && typed < length && <span data-caret aria-hidden="true" className="ml-px inline-block h-3.5 w-px translate-y-0.5 bg-foreground/60" />}
                {rest && <span aria-hidden="true" className="invisible">{rest}</span>}
              </p>
              <p ref={metaRef} data-meta className="relative truncate text-xs leading-4 text-muted-foreground">
                {item.meta}
              </p>
            </div>
            {item.status && (
              <span className="relative inline-flex shrink-0">
                {typing && <span ref={(node) => { placeholders.current.pill = node; }} data-placeholder="pill" aria-hidden="true" className="absolute inset-0 rounded-full bg-muted-foreground/15" />}
                <span ref={pillRef} data-pill data-tone={tone} className={`relative inline-flex h-5 items-center gap-1.5 rounded-full px-2 text-[11px] font-medium ${PILL[tone].pill}`}>
                  <span aria-hidden="true" className={`size-1.5 rounded-full ${PILL[tone].dot}`} />
                  {item.status.label}
                </span>
              </span>
            )}
          </>
        )}
      </div>
    </li>
  );
}

export function FirstItemEmptyState({
  items,
  defaultItems,
  onItemsChange,
  onCreate,
  onImport,
  onItemSelect,
  title = "Items",
  noun = "item",
  nounPlural,
  copy,
  ghostRows = 3,
  minRows,
  typingSpeed = 24,
  renderItem,
  actions,
  className = "",
  ref,
  ...rest
}: FirstItemEmptyStateProps) {
  const reduced = useReducedMotion();
  const modality = React.useRef("pointer" as "pointer" | "keyboard");
  const baseId = React.useId();
  const headingId = `${baseId}-empty-title`;
  const plural = nounPlural ?? `${noun}s`;
  const controlled = items !== undefined;
  const [localItems, setLocalItems] = React.useState(defaultItems ?? []);
  const list = items ?? localItems;
  const listKey = list.map((item) => item.id).join("|");
  const empty = list.length === 0;
  const [pending, setPending] = React.useState(false);
  const [error, setError] = React.useState(false);
  const [materializing, setMaterializing] = React.useState([] as string[]);
  const [focusId, setFocusId] = React.useState(null as string | null);
  const [pendingGhost, setPendingGhost] = React.useState(null as PendingGhostState | null);
  const [collapsing, setCollapsing] = React.useState(0);
  const [overlayLeaving, setOverlayLeaving] = React.useState(false);
  const [leaving, setLeaving] = React.useState([] as FirstItem[]);
  const [everListed, setEverListed] = React.useState(list.length > 0);
  const [announce, setAnnounce] = React.useState("");

  const rootRef = React.useRef(null as HTMLDivElement | null);
  const toolbarRef = React.useRef(null as HTMLDivElement | null);
  const toolbarInnerRef = React.useRef(null as HTMLDivElement | null);
  const overlayRef = React.useRef(null as HTMLDivElement | null);
  const ghostRefs = React.useRef([] as (HTMLDivElement | null)[]);
  const listRef = React.useRef(list);
  listRef.current = list;
  const reducedRef = React.useRef(reduced);
  reducedRef.current = reduced;
  const alive = React.useRef(true);
  const pendingRef = React.useRef(false);
  const mounted = React.useRef(false);
  const known = React.useRef(new Set(list.map((item) => item.id)));
  const previousCount = React.useRef(list.length);
  const previousList = React.useRef(list);
  const timers = React.useRef([] as number[]);
  const toolbarAnimation = React.useRef(null as Animation | null);

  const text = {
    title: copy?.title ?? `No ${plural} yet`,
    description: copy?.description ?? `Create your first ${noun} to get started.`,
    createLabel: copy?.createLabel ?? `Create ${noun}`,
    creatingLabel: copy?.creatingLabel ?? "Creating…",
    retryLabel: copy?.retryLabel ?? "Try again",
    importLabel: copy?.importLabel ?? "Import",
    errorText: copy?.errorText ?? "Couldn't create",
    toolbarCreateLabel: copy?.toolbarCreateLabel ?? "Create",
  };

  const schedule = (callback: () => void, ms: number) => {
    const id = window.setTimeout(callback, ms);
    timers.current.push(id);
  };

  React.useEffect(() => {
    alive.current = true;
    const byPointer = () => { modality.current = "pointer"; };
    const byKeyboard = () => { modality.current = "keyboard"; };
    document.addEventListener("pointerdown", byPointer, true);
    document.addEventListener("keydown", byKeyboard, true);
    return () => {
      alive.current = false;
      document.removeEventListener("pointerdown", byPointer, true);
      document.removeEventListener("keydown", byKeyboard, true);
      for (const id of timers.current) window.clearTimeout(id);
      toolbarAnimation.current?.cancel();
    };
  }, []);

  React.useLayoutEffect(() => {
    const fresh = list.filter((item) => !known.current.has(item.id)).map((item) => item.id);
    known.current = new Set(list.map((item) => item.id));
    if (fresh.length === 0) return;
    setMaterializing((current) => [...current.filter((id) => known.current.has(id)), ...fresh]);
  }, [listKey]);

  React.useLayoutEffect(() => {
    const was = previousCount.current;
    const now = list.length;
    previousCount.current = now;
    const show = now > 0;
    const toolbar = toolbarRef.current;
    const inner = toolbarInnerRef.current;
    const first = !mounted.current;
    mounted.current = true;
    if (toolbar && inner) {
      const from = toolbar.getBoundingClientRect().height;
      const to = show ? inner.offsetHeight : 0;
      toolbar.style.height = `${to}px`;
      if (!first && (was === 0) !== (now === 0) && !reduced && typeof toolbar.animate === "function") {
        toolbarAnimation.current?.cancel();
        toolbarAnimation.current = toolbar.animate([{ height: `${from}px` }, { height: `${to}px` }], { duration: TOOLBAR, easing: EASE });
        inner.animate(
          show ? [{ opacity: 0, transform: "translateY(-6px)" }, { opacity: 1, transform: "translateY(0)" }] : [{ opacity: 1 }, { opacity: 0 }],
          { duration: show ? TOOLBAR : OVERLAY_OUT, easing: EASE },
        );
      }
    }
    if (first) {
      previousList.current = list;
      return;
    }
    if (was === 0 && now > 0) {
      setEverListed(true);
      if (!reduced) {
        const extra = Math.max(0, ghostRows - 1);
        setCollapsing(extra);
        setOverlayLeaving(true);
        schedule(() => setCollapsing(0), GHOST_OUT + GHOST_STAGGER * Math.max(0, extra - 1) + 40);
        schedule(() => setOverlayLeaving(false), OVERLAY_OUT + 20);
      }
    } else if (was > 0 && now === 0) {
      if (!reduced) {
        const gone = previousList.current;
        setLeaving(gone);
        schedule(() => setLeaving([]), LEAVE + LEAVE_STAGGER * Math.max(0, gone.length - 1) + 40);
      }
    }
    previousList.current = list;
  }, [list.length]);

  React.useEffect(() => {
    if (reduced || !empty) return;
    const animations: Animation[] = [];
    ghostRefs.current.forEach((card, index) => {
      if (!card || !card.isConnected || typeof card.animate !== "function") return;
      if (pending && index === 0) {
        animations.push(card.animate([{ opacity: 0.92 }], { duration: 200, easing: EASE, fill: "forwards" }));
        return;
      }
      animations.push(card.animate([{ opacity: 0.5 }, { opacity: 0.8 }, { opacity: 0.5 }], { duration: BREATH, delay: -index * BREATH_STAGGER, iterations: Number.POSITIVE_INFINITY, easing: "ease-in-out" }));
    });
    return () => animations.forEach((animation) => animation.cancel());
  }, [reduced, empty, pending, ghostRows]);

  React.useLayoutEffect(() => {
    const node = overlayRef.current;
    if (!overlayLeaving || !node || typeof node.animate !== "function") return;
    const animation = node.animate([{ opacity: 1, transform: "translateY(0)" }, { opacity: 0, transform: "translateY(-12px)" }], { duration: OVERLAY_OUT, easing: EASE_IN, fill: "forwards" });
    return () => animation.cancel();
  }, [overlayLeaving]);

  React.useLayoutEffect(() => {
    const node = overlayRef.current;
    if (!empty || !everListed || reduced || !node || typeof node.animate !== "function") return;
    const animation = node.animate([{ opacity: 0, transform: "translateY(8px)" }, { opacity: 1, transform: "translateY(0)" }], { duration: 300, delay: 120, easing: EASE, fill: "backwards" });
    return () => animation.cancel();
  }, [empty]);

  const create = async () => {
    if (pendingRef.current) return;
    pendingRef.current = true;
    const hadItems = listRef.current.length > 0;
    setPending(true);
    setError(false);
    setAnnounce("");
    if (hadItems) setPendingGhost("in");
    const started = performance.now();
    let created = null as FirstItem | null;
    let failed = false;
    try {
      const value: unknown = await Promise.resolve(onCreate());
      if (isFirstItem(value)) created = value;
    } catch {
      failed = true;
    }
    if (!alive.current) return;
    // Let the shimmer finish its sweep so a fast response does not cut the band in half.
    if (!reducedRef.current) {
      const elapsed = performance.now() - started;
      const remaining = SHIMMER - (elapsed % SHIMMER);
      if (remaining > 24) await wait(remaining);
      if (!alive.current) return;
    }
    pendingRef.current = false;
    if (failed) {
      setPending(false);
      setError(true);
      setPendingGhost(hadItems ? "out" : null);
      setAnnounce(`${text.errorText}. ${text.retryLabel}.`);
      return;
    }
    if (created) {
      const next = [created, ...listRef.current];
      setFocusId(created.id);
      if (!controlled) setLocalItems(next);
      onItemsChange?.(next);
      setAnnounce(`${created.title} created`);
    }
    setPending(false);
    setPendingGhost(null);
  };

  const settle = (id: string) => {
    setMaterializing((current) => current.filter((value) => value !== id));
    setFocusId((current) => (current === id ? null : current));
  };
  const keyboardFocus = () => modality.current === "keyboard";

  const onListKeyDown = (event: React.KeyboardEvent) => {
    const target = event.target;
    if (!(target instanceof HTMLElement) || !target.hasAttribute("data-row")) return;
    const rows = Array.from(event.currentTarget.querySelectorAll("[data-row]:not([aria-hidden])")).filter((node): node is HTMLElement => node instanceof HTMLElement);
    const index = rows.indexOf(target);
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      const item = list.find((candidate) => candidate.id === target.dataset.id);
      if (item) onItemSelect?.(item);
      return;
    }
    let next = -1;
    if (event.key === "ArrowDown") next = Math.min(rows.length - 1, index + 1);
    else if (event.key === "ArrowUp") next = Math.max(0, index - 1);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = rows.length - 1;
    if (next < 0 || next === index) return;
    event.preventDefault();
    rows[next]?.focus();
  };

  const count = `${list.length} ${list.length === 1 ? noun : plural}`;
  const createLabel = pending ? text.creatingLabel : error ? text.retryLabel : text.createLabel;
  const toolbarLabel = pending ? text.creatingLabel : error ? text.retryLabel : text.toolbarCreateLabel;
  const widest = (labels: string[]) => labels.reduce((longest, label) => (label.length > longest.length ? label : longest), "");
  const overlaySizer = widest([text.createLabel, text.creatingLabel, text.retryLabel]);
  const toolbarSizer = widest([text.toolbarCreateLabel, text.creatingLabel, text.retryLabel]);
  const CreateIcon = error && !pending ? RotateCcw : Plus;
  const transition = overlayLeaving || collapsing > 0 ? "to-list" : leaving.length > 0 ? "to-empty" : "none";

  return (
    <div
      {...rest}
      ref={(node) => {
        rootRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) (ref as { current: HTMLDivElement | null }).current = node;
      }}
      data-slot="first-item-empty-state"
      data-state={empty ? "empty" : "list"}
      data-pending={pending ? "true" : "false"}
      data-error={error ? "true" : "false"}
      data-count={list.length}
      data-transition={transition}
      className={`relative w-full rounded-2xl bg-card text-card-foreground shadow-sm ring-1 ring-border ${className}`}
    >
      <header className="flex h-12 items-center justify-between gap-3 border-b border-border px-4">
        <h2 data-heading className="truncate text-sm font-medium leading-5">{title}</h2>
        {actions}
      </header>

      <div
        ref={toolbarRef}
        data-toolbar
        data-visible={empty ? "false" : "true"}
        aria-hidden={empty}
        inert={empty}
        className="overflow-hidden"
      >
        <div ref={toolbarInnerRef} className="flex h-10 items-center justify-between gap-3 border-b border-border px-4">
          <span data-count data-error={error ? "true" : "false"} className={`truncate text-xs tabular-nums ${error ? "text-destructive" : "text-muted-foreground"}`}>
            {error ? text.errorText : count}
          </span>
          <div className="flex shrink-0 items-center gap-1">
            {onImport && (
              <button type="button" data-import data-place="toolbar" onClick={onImport} className={SMALL_GHOST}>
                {text.importLabel}
              </button>
            )}
            <button type="button" data-create data-place="toolbar" onClick={create} disabled={pending} aria-busy={pending} className={SMALL_PRIMARY}>
              <CreateIcon className="size-3.5" aria-hidden="true" />
              <span className="grid text-left">
                <span aria-hidden="true" className="invisible col-start-1 row-start-1">{toolbarSizer}</span>
                <span data-label className="col-start-1 row-start-1">{toolbarLabel}</span>
              </span>
            </button>
          </div>
        </div>
      </div>

      <div data-list-area className="relative p-4">
        <ul
          role="list"
          aria-label={title}
          aria-busy={pending ? true : undefined}
          onKeyDown={onListKeyDown}
          className="-my-[3px]"
          style={minRows !== undefined && !empty ? { minHeight: minRows * PITCH } : undefined}
        >
          {empty
            ? Array.from({ length: ghostRows }, (_, index) => (
                <GhostRow
                  key={`ghost-${index}`}
                  index={index}
                  appear={everListed}
                  reduced={reduced}
                  shimmer={pending && index === 0 && !reduced}
                  register={(node) => { ghostRefs.current[index] = node; }}
                />
              ))
            : null}
          {pendingGhost !== null && !empty && <PendingGhost state={pendingGhost} reduced={reduced} onGone={() => setPendingGhost(null)} />}
          {list.map((item) => (
            <Row
              key={item.id}
              item={item}
              materialize={materializing.includes(item.id)}
              reduced={reduced}
              typingSpeed={typingSpeed}
              focusOnMount={focusId === item.id}
              keyboardFocus={keyboardFocus}
              renderItem={renderItem}
              onSettled={settle}
              onSelect={onItemSelect}
            />
          ))}
          {Array.from({ length: collapsing }, (_, order) => (
            <CollapsingGhost key={`collapsing-${order}`} index={order + 1} order={order} />
          ))}
        </ul>

        {leaving.length > 0 && (
          <ul data-leaving aria-hidden="true" className="pointer-events-none absolute inset-x-4 top-4 -my-[3px]">
            {leaving.map((item, order) => (
              <Row key={`leaving-${item.id}`} item={item} materialize={false} reduced={reduced} typingSpeed={typingSpeed} focusOnMount={false} keyboardFocus={keyboardFocus} leaveOrder={order} renderItem={renderItem} />
            ))}
          </ul>
        )}

        {(empty || overlayLeaving) && (
          <div
            ref={overlayRef}
            data-overlay
            data-leaving={overlayLeaving ? "true" : "false"}
            role="region"
            aria-labelledby={headingId}
            inert={overlayLeaving}
            className="absolute inset-0 flex flex-col items-center justify-center px-6 text-center"
          >
            <span data-fog aria-hidden="true" className="pointer-events-none absolute inset-0 bg-radial from-card from-30% to-transparent to-78%" />
            <span data-overlay-icon aria-hidden="true" className="relative flex size-9 items-center justify-center rounded-xl bg-muted text-muted-foreground ring-1 ring-border/60">
              {copy?.icon ?? <FolderPlus className="size-4" />}
            </span>
            <h3 id={headingId} data-overlay-title className="relative mt-3 text-sm font-medium leading-5">{text.title}</h3>
            <p data-overlay-text data-error={error ? "true" : "false"} className={`relative mt-1 text-xs leading-4 ${error ? "text-destructive" : "text-muted-foreground"}`}>
              {error ? text.errorText : text.description}
            </p>
            <div className="relative mt-3 flex items-center gap-2">
              <button type="button" data-create data-place="overlay" onClick={create} disabled={pending} aria-busy={pending} className={PRIMARY}>
                <CreateIcon className="size-3.5" aria-hidden="true" />
                <span className="grid text-left">
                  <span aria-hidden="true" className="invisible col-start-1 row-start-1">{overlaySizer}</span>
                  <span data-label className="col-start-1 row-start-1">{createLabel}</span>
                </span>
              </button>
              {onImport && (
                <button type="button" data-import data-place="overlay" onClick={onImport} className={GHOST}>
                  {text.importLabel}
                </button>
              )}
            </div>
          </div>
        )}
      </div>
      <p role="status" aria-live="polite" className="sr-only">{announce}</p>
    </div>
  );
}

